*eliminating the Media companies themselves (Pearson PLC,News Corp, NYT, Dolan Media Company);
proc sql;
	create table mn.day as
	select distinct *
	from print.dates, print.list5 (where=(lpermno ne .))
	having lpermno not in (13963,47466,90442,88595,92243)
