*bring in ads;
proc sql;
	create table mn.day1 (drop = weekly biweekly monthly bimonthly ad_company company_num companyid 
				ciq_country industry b2b b2b_consumer luxury fashion lifestyle construction daily 
				add_sub_category category_cnt regional foreign total_titles ad_cnt type status ticker 
				exchangename s_date e_date wsj financial day_med small_ad cover corporate ind state type magcirc wkdy) as
	select distinct a.*, weekday(b.date) as dow, b.*
	from mn.day as a
	left join print.ads4 (where=(lpermno ne . and daily eq 1)) as b on a.company_num eq b.company_num and a.date eq b.date;
quit;

proc sort data=mn.day1;
by lpermno date;
run;

data  mn.day1;
	set  mn.day1;
	if dow in (1,7) and sun_sat ne . then circ = sun_sat;
run;

/* Collapse ad data: 2,930,766 observations in mn.day2 */

*News Stories;
proc sql;
	create table mn.day2c as
	select distinct a.*, count(distinct rp_story_id) as article_cnt, 
	max(case when b.category eq "product-release" then 1
	else 0 end)	as product_release
	from mn.day2b as a
	left join print.rp_news (where=(group ne "stock-prices" and group ne "order-imbalances" and relevance eq 100)) as b on a.lpermno eq b.lpermno and a.date eq b.date
	group by a.lpermno, a.date
	order by lpermno, date;
quit;

*Holidays;
proc sql;
	create table mn.day2d as
	select distinct a.*, 
		case when b.holiday ne . then 1
		else 0
		end as holiday
	from mn.day2c as a
	left join crsp.holidays as b on a.date eq b.holiday
	order by lpermno, a.date;
quit;

*Bring in CRSP Identifiers;
proc sql;
	create table mn.day3 as
	select distinct  permco, cusip, a.*
	from mn.day2d as a
	left join crsp.companies as c on a.lpermno eq c.permno
	order by a.lpermno, date;
quit;

/* correcting a few permco/cusip */
data mn.day3;
	set mn.day3;
	if lpermno eq 13115 then do; permco = 12054; cusip = '68569140'; end;
	if lpermno eq 13188 then do; permco = 53972; cusip = '73744610'; end;
	if lpermno eq 13963 then do; permco = 54433; cusip = '65249B10'; end;
run;


*Institutional Ownership;
proc sql;
	create table mn.day3 as
	select distinct  a.*, b.inst_inv_share
	from mn.day3 as a
	left join thomson.f13_2007_20132 as b on a.cusip eq b.cusip and b.date le a.date lt b.lag_date
	order by lpermno, date;
quit;


****************************
*Google and EDGAR Data;
****************************;

*Google Data;
proc sql;
	create table mn.day5 as
	select distinct a.*, max(returns_box) as returns_box, max(any_flag) as ticker_flag,
		log(sum(b.svi_d_scaled)) as lnsvi
	from mn.day3 as a
	left join go.daily_svi4 as b on b.permco eq a.permco and a.date eq b.date 
	group by a.lpermno, a.date
	order by a.lpermno, date;
quit;

proc sql;
	create table mn.day5 as
	select distinct  a.*, log(sum(b.svi_d_scaled)) as lnsvi_name
	from mn.day5 as a
	left join go.daily_fullnames2 as b on b.permco eq a.permco and a.date eq b.date 
	group by a.lpermno, a.date
	order by a.lpermno, date;
quit;

*Edgar Data;
proc sql;
	create table mn.day5 as
	select distinct a.*, log(b.annual+1) as ln_hits_k, log(b.all+1) as ln_hits_all, log(b.fundamental+1) as ln_hits_fund
	from mn.day5 as a
	left join edgar.downloads_master as b on a.gvkey eq b.gvkey and a.date eq b.date
	order by lpermno, date;
quit;

*First/last day of Edgar data;
proc sql;
	create table first_Edgar as
	select distinct lpermno, min(date) as mn_edate format mmddyy9., max(date) as mx_edate format mmddyy9.
	from mn.day5 (where=(ln_hits_all ne  .))
	group by lpermno;
quit;

*add in advertiser identifier and restrict to time period when advertising data available;
proc sql;
	create table mn.day6 as
	select distinct  *
	from mn.day5 as a
	left join first_edgar as c on a.lpermno eq c.lpermno;
quit;

proc univariate data=mn.day6;
var ln_hits_k;
run;

data mn.day6;
	set mn.day6;
	if ln_hits_k eq . and date ge mn_edate and date le mx_edate then ln_hits_k = 0;
	if ln_hits_all eq . and date ge mn_edate and date le mx_edate then ln_hits_all = 0;
	if ln_hits_fund eq . and date ge mn_edate and date le mx_edate then ln_hits_fund = 0;
run;

proc sort data=mn.day6;
by lpermno dow date; 
run;

*Edgar filing dates;
data edgar_filing;
	set edgar.edgar_8k_10k_10q_filing;
length gvkey2 $6;
	gvkey2 = compress(gvkey);
	x = length(gvkey2);
	if x lt 6 and x gt 1 then do;
		gvkey2 = repeat('0',5-length(gvkey2))||gvkey2;
	end;
	drop gvkey x;
run;
proc sql;
	create table mn.day6 as
	select distinct a.*, case when b.file_date ne . then 1 else 0 end as edgar_file_date
	from mn.day6 as a
	left join edgar_filing as b on a.gvkey eq b.gvkey2 and a.date eq b.file_date;
quit;

data qea;
	set dis.comp_full_sample;
	if(2006 <= year <= 2014);
	if(eadate_crsp = eadate_ibes);
	if(shrcd in (10 11));	

	drop nq_test expected2 deflator eadate_ibes shrcd win75_end win70_end win14_end win2_end comp_zip tzone mergeall win_beg win2_end_nq pead_nq_lag eadate_nq eadate_nq_lag datadate_nq_lag;
	attrib _all_ label = '';
	keep replag volatility persist ue_dec size_dec btm_dec turn instown   log_analyst eadate_crsp permno fqtr actual sue1 ue ue_dec sue1_dec ;
run;
proc sql;
	create table mn.day8 as
	select distinct a.*,
		case when b.eadate_crsp ne . then 1
		when b.eadate_crsp eq . then 0
		end as qea_dummy
	from mn.day6  as a
	left join qea as b on a.lpermno eq b.permno and a.date eq b.eadate_crsp
	order by lpermno, date;
quit;

proc sort nodupkey;
by lpermno date;
run;

*Industry;
proc sql;
	create table mn.day8a as
	select distinct a.*, b.datadate, prcc_f * csho as mve, ib/at as roa, lt/at as lev, ceq/calculated mve as bm_comp, b.at, b.revt, b.ni, b.xad, b.sich 
	from mn.day8 as a 
	left join comp.funda_2013 as b on a.gvkey eq b.gvkey and intnx('year',a.date,-1,'S') le b.datadate lt a.date
	order by lpermno, date, datadate desc;
quit;

*Dealing with fiscal year end changes. remove the least recent filing;
proc sort data=mn.day8a (drop = datadate) nodupkey out=mn.day8a dupout=dups;
by lpermno date;
run;

*assign Fama French Industry codes;
%ind_ff48(mn.day8a, mn.day8a, sich, bin_var, ind_code);
%ind_ff12 (mn.day8a, mn.day8a, sich, bin_var, ind_code12 );

proc sql;
	create table mn.day8b (drop = permno) as
	select distinct *
	from mn.day8a as a
	left join print.ret_volatility as b on a.lpermno eq b.permno and a.date eq b.date
	order by lpermno, date;
quit;

*bring in CRSP variables;
proc sql;
	create table mn.day8b as
	select distinct a.*, shrout, vol, b.prc as prc2, prc_lag, size, bm
	from mn.day8b as a
	left join crsp.dsf_index_2013 as b	on a.lpermno eq b.permno and a.date eq b.date
	order by lpermno, date;
quit;

*TAQ volume;
proc sql;
	create table mn.day8b as
	select distinct  a.*, dollar_depth, effectivespread_percent_sw, quotedspread_percent, turn
	from mn.day8b as a
	left join taq.mr_taq as b on a.lpermno eq b.permno and a.date eq b.date
	order by lpermno, date;
quit;

