*Annual Averages: Table 1 Panel A;
proc sql; 
	create table ads3 as
	select year(date) as year, count(publication) as ads, count(distinct lpermno) as firms, count(distinct brand_num) as brands, 
	count(distinct publication_num) as publications, sum(est_value2) as value
	from mn.day1 (where=(publication ne ''))
	where lpermno in (select distinct lpermno from mn.day8d)
	group by year;
quit;

*Full Sample Average Table 1 Panel A;
proc sql; 
	create table ads2 as
	select  count(publication) as ads, count(distinct lpermno) as firms, count(distinct brand_num) as brands, 
	count(distinct publication_num) as publications, sum(est_value2) as value
	from mn.day1 (where=(publication ne ''))
	where lpermno in (select distinct lpermno from mn.day8d);
quit;


*Brands and Titles: Table 1 Panel B;
proc sql;
	create table sum1 as
	select distinct lpermno, year(date) as year, count(publication) as ads, count(distinct date) as ad_days, sum(est_value2)/1000000 as value, 
	count(distinct brand_num) as brands, count(distinct publication_num) as publications
	from mn.day1 (where=(publication ne ''))
	where lpermno in (select distinct lpermno from mn.day8d)
	group by lpermno, year;
quit;

proc means data=sum1 mean median stddev p1 p99;
var ads ad_days value brands publications;
run;


*Number of titles conditional on advertising;
proc sql;
	create table sum2 as
	select distinct lpermno, year(date) as year, mean(titles_cnt) as titles_cnt_avg
	from mn.day8d (where=(ads gt 0))
	group by lpermno, year;
quit;
proc means data=sum2 mean median stddev p1 p99;
var titles_cnt_avg;
run;


*Ads by tile: Table 1 Panel D;
proc sql;
	create table titles as
	select distinct publication, count(*) as ads, min(date) as date format mmddyy9., count(distinct date) as ad_days
	from mn.day1 (where=(publication ne ''))
	where lpermno in (select distinct lpermno from mn.day8d)
	group by publication
	ORDER	BY ads DESCENDING;
quit;



/* Table 2 Panel  C*/
*Preferred day of week;
proc sql;
	create table days2 as
	select distinct lpermno, companyname, ind_code12, dow, sum(ads) as ads, count(distinct date) as dates_w_ad
	from mn.day8d (where=(ads > 0))
	group by lpermno, dow
	order by lpermno, dow, ind_code12 descending;
quit;

proc sort data=days2 nodupkey;
by lpermno dow;
run;

proc sql;
	create table days3 as
	select distinct lpermno,  companyname, ind_code12, dow as dow_freq label "Fav DOW", max(ads) as max_day label "Adds on Fav DOW", 
		count(distinct dow) as days label "Days of week with ads",
		sum(ads) as ads_all label "All ads placed", sum(dates_w_ad) as dates_w_ad, calculated max_day / calculated ads_all as percent
	from days2
	group by lpermno
	having ads eq max_day;
quit;

proc sql;
	create table days4 as
	select distinct dow_freq, count(*) as firms, mean(percent) as avg_percent
	from days3
	group by dow_freq
	order by dow_freq;
quit;

proc sql;
	create table days4a as
	select distinct dow_freq, ind_code12, count(*) as firms, mean(percent) as avg_percent
	from days3
	group by dow_freq, ind_code12
	order by ind_code12, dow_freq;
quit;
